package render
import (
    "receipt-render-engine/internal/html"
    "receipt-render-engine/internal/text"
)
type Renderer func(string) string
var engines = map[string]Renderer{"shop": text.RenderReceipt}
func init() { engines["shop"] = html.RenderReceipt }
func Make(name string) string { return engines[name]("Sale closed") }

